/** 
 * Java program implementing a binary search algorithm on an array of integers
 **/

import java.util.Scanner;

class BinarySearch {

    // function that performs binary search on a given array
    public static int binarySearch(int arr[], int key) {

        int start = 0;
        int end = arr.length - 1;

        while (start <= end) {

            int mid = start + (end - start) / 2;

            // If key is found at mid, return it
            if (arr[mid] == key) {
                return mid;
            }

            // look in the left half if key is smaller
            else if (arr[mid] > key) {
                end = mid - 1;
            }

            // look in the right half if key is larger
            else {
                start = mid + 1;
            }

        }

        // return -1 if key is not found in array
        return -1;
    }


    // main function to take user input and test binary search
    public static void main(String args[]) {

        Scanner sc = new Scanner(System.in);

        System.out.println("Enter the size of the array:");
        int size = sc.nextInt();

        int[] arr = new int[size];

        System.out.println("Enter the elements of the array in sorted order:");

        for (int I = 0; I < size; i++) {
            arr[i] = sc.nextInt();
        }

        System.out.println("Enter the key to be searched:");
        int key = sc.nextInt();

        // perform binary search on array
        int index = binarySearch(arr, key);

        if (index == -1) {
            System.out.println("Key not found in array");
        } else {
            System.out.println("Key found at index " + index);
        }

        sc.close();
    }
}

