class Stack:
    """
    Stack data structure implementation.
    """

    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def peek(self):
        """
        Returns the top element in the stack without modifying the stack. If the stack is empty,
        return None.
        """
        if not self.is_empty():
            return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0
