object TagCloudGenerator {
  val stopWords = Set("the", "and", "a", "an", "in", "of", "to", "for", "that", "with", "on", "at", "from", "by", "is", "was", "it", "this", "as", "be", "they", "or", "not", "but", "which", "their", "there", "if", "we", "are", "all", "have", "your", "one", "had", "has", "he", "she", "him", "her", "his", "hers", "you", "me", "i", "my", "we", "our", "us")

  def main(args: Array[String]): Unit = {
    val fileName = args(0)
    val freqThreshold = if (args.length > 1) args(1).toInt else 0

    val wordCounts = MutableMap.empty[String, Int]
    for (line <- Source.fromFile(fileName).getLines()) {
      for (word <- line.split("\\W+")) {
        val cleanedWord = word.toLowerCase
        if (!stopWords.contains(cleanedWord)) {
          val count = wordCounts.getOrElse(cleanedWord, 0) + 1
          wordCounts.update(cleanedWord, count)
        }
      }
    }

    val sortedWordCounts = ListMap(wordCounts.toSeq.sortWith(_._2 > _._2):_*)
    println("Word\tFrequency")
    for ((word, count) <- sortedWordCounts if count >= freqThreshold) {
       println(s"$word\t$count")
    }
  }
}
